        if q < 0.01:
            q = 0.01  # ensure we never evaluate at exactly q=0
        d = relative_deviation(q)
        if d > max_dev:
            max_dev = d
        if d > tolerance:
            dev_above += 1
    print(f"Maximum relative deviation: {max_dev:.3e}")
    print(f"Samples with deviation >5 %: {dev_above}/{samples}")

if __name__ == "__main__":
