        with open(path, 'r') as f:
            return json.load(f)
    except Exception as e:
        print(f'Failed to read GWTC catalog: {e}', file=sys.stderr)
        return None

def main():
    catalog = load_catalog()
    if not catalog:
        # Fallback: use a tiny representative sample of GW events
        events = [
            {"name": "GW150914",   "mass_1_source": 36.0, "mass_2_source": 32.0, "final_mass_source": 62.0},
            {"name": "GW170817",   "mass_1_source": 1.4,  "mass_2_source": 1.3,  "final_mass_source": 2.8}
        ]
    else:
        events = catalog.get('events', [])

    total = len(events)
    print(f"Processing {total} events (including fallback samples).")

    discrepancies = []
    for ev in events:
        m1 = ev.get('mass_1_source')
        m2 = ev.get('mass_2_source')
        mf = ev.get('final_mass_source')
        if None in (m1, m2, mf):
            print("Skipping incomplete event:", ev.get('name', "unknown"))
            continue
        # Simple sanity‑check: ensure masses are positive and final mass ≤ sum
        if m1 <= 0 or m2 <= 0 or mf <= 0 or mf > (m1 + m2):
