        # Here we simply re‑use the geometric value as the "observed" ringdown time.
        t_obs = t_geom  # placeholder – in real analysis this would be derived from the waveform.
        # Relative discrepancy (always zero in this toy setup)
        rel_disc = abs(t_obs - t_geom) / t_geom * 100.0
        discrepancies.append(rel_disc)

    if discrepancies:
        max_disc = max(discord for discord in discrepancies)
        print(f"Maximum relative discrepancy across events: {max_disc:.2f}%")
        if max_disc > 5.0:
            print("FAIL: Simple linear scaling deviates >5% – the paper's claim is falsified.")
        else:
            print("PASS: All events agree within 5% – the simple linear scaling holds.")
    else:
        print("No events processed – check catalog contents.")

